-- Remove remaining source narration from weapon descriptions.
UPDATE weapon_dictionary SET description='A26형 블레킹에급은 사브 코쿰스가 설계한 스웨덴의 차세대 재래식 잠수함이다. 길이 66.1m, 수상 배수량 1,925t이며 디젤 엔진 3기와 스털링 AIP 엔진 3기를 갖춘다. 승조원은 17~26명이고 어뢰, 기뢰, ROV를 운용하며 직경 1.5m의 유연탑재구를 갖는다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='a26';
UPDATE weapon_dictionary SET description='안작급은 독일 Blohm+Voss의 MEKO 200 설계를 바탕으로 한 호위함이다. Tenix Defence Systems가 호주에서 건조했으며 호주 해군 10척과 뉴질랜드 해군 2척으로 구성된다. 배수량 3,600t, 전장 118m, 최고속도 27노트, 승조원 177명이다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='anzac-class';
UPDATE weapon_dictionary SET description='애로헤드 140은 Babcock이 개발한 138.7m급 호위함 설계로, 영국 Type 31 Inspiration급과 인도네시아 Merah Putih급의 기반이다. Type 31 계획 제원은 배수량 5,700t, 최고속도 26노트, 승조원 약 100명이다. 영국형 5척과 인도네시아형 2척이 건조 중이다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='arrowhead-140';
UPDATE weapon_dictionary SET description='바르톨로메우 디아스급은 포르투갈 해군의 네덜란드 건조 호위함 2척이다. 함명은 F333 Bartolomeu Dias와 F334 D. Francisco de Almeida다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='bartolomeu-dias-class';
UPDATE weapon_dictionary SET description='vz.77 DANA는 체코슬로바키아가 개발한 Tatra 815 8x8 차체 기반의 152mm 차륜형 자주포다. 총중량 29.25t, 승무원 4+1명, 도로 최고속도 80km/h, 항속거리 최대 740km이며 크기는 11.156×3.000×3.350m다. Tatra 3-920.52 V-12 엔진을 사용한다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='dana';
UPDATE weapon_dictionary SET description='Bonifaz급 F-110은 스페인 해군이 도입 중인 차세대 호위함으로, 5척이 건조 중이며 아직 취역하지 않았다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='f110-bonifaz-class';
UPDATE weapon_dictionary SET description='K9 Thunder는 한화에어로스페이스가 생산하는 한국의 155mm 52구경 궤도형 자주포다. 전투중량 46.3t, 승무원 5명, 도로 최고속도 67km/h이며 표준탄 사거리는 30km, 로켓보조탄 사거리는 40km다. K10 탄약보급차와 K9A1, K9 Vajra-T, AS9 Huntsman, K9FIN, VIDAR, K9A1EGY 파생형이 있다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='k9-thunder';
UPDATE weapon_dictionary SET description='Lynx KF41은 라인메탈의 궤도형 보병전투차다. 승무원 3명과 보병 8명을 태우며 Lance 2 포탑에 30mm 기관포와 동축기관총, 선택형 대전차미사일을 장착한다. 헝가리는 7개 파생형 218대를 계약했으며 잘라에게르세그 공장에서 생산된다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='lynx-kf41';
UPDATE weapon_dictionary SET description='MEKO A-200은 TKMS의 모듈형 호위함 설계 계열이다. 하위형은 A-200 SAN, A-200 AN, A-200 EN이다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='meko-a200';
UPDATE weapon_dictionary SET description='NASAMS는 콩스베르그와 Raytheon이 공동 개발한 지상 기반 방공 체계다. 표준 포대는 사격통제소, AN/MPQ-64F1 Sentinel 레이더, 전자광학 센서와 AMRAAM 발사대로 구성되며 레이더와 발사대를 사격통제소에서 20km 이상 떨어뜨려 배치할 수 있다. AMRAAM ER과 AIM-9X-2를 운용하며 미국과 노르웨이 등 13개국이 도입했다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='nasams';
UPDATE weapon_dictionary SET description='Pandur II는 오스트리아에서 개발한 8x8 차륜형 장갑차다. 포르투갈군은 SP30 포탑형을 보병전투차로 운용하며 해당 형식은 군 현대화 사업에 포함된다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='pandur-ii';
UPDATE weapon_dictionary SET description='Patria CRO 30L은 크로아티아군의 Patria AMV 8x8 보병전투차형이다. UT30MK2 원격무장에 30mm MK44S Bushmaster II 기관포, 7.62mm M240 기관총, Spike LR 대전차미사일 2연장 발사기를 탑재한다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='patria-amv';
UPDATE weapon_dictionary SET description='Pizarro는 스페인의 궤도형 보병전투차다. 승무원 3명과 보병 7명을 태우며 30mm 기관포를 장착한다. 최고속도 70km/h, 항속거리 500km다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='pizarro';
UPDATE weapon_dictionary SET description='PLZ-45는 Type 88로도 불리는 NORINCO의 중국제 155mm 45구경 궤도형 자주포다. 전투중량 33t, 승무원 5명, 최고속도 56km/h, 항속거리 450km이며 525마력 Deutz BF12 L413FC 엔진을 탑재한다. 차체 크기는 6.1×3.23×2.59m다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='plz-45';
UPDATE weapon_dictionary SET description='Puma는 PSM이 개발한 독일 육군의 궤도형 보병전투차다. 무인 포탑에 30mm MK 30-2/ABM 기관포와 5.56mm MG4 기관총을 장착하고 MELLS 대전차미사일을 운용한다. 승무원 3명과 보병 6명이 탑승하며 전투중량은 형상에 따라 31.45~43t이고 엔진 출력은 800kW, 최고속도는 70km/h다. 2025년 12월 독일은 200대를 추가 주문했다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='puma-ifv';
UPDATE weapon_dictionary SET description='PzH 2000은 KNDS Deutschland가 생산하는 155mm L52 궤도형 자주포다. 전투중량 57t, 전장 11.7m, 전폭 3.5m, 전고 3.4m이며 736kW 엔진을 탑재한다. 탄약 60발과 장약 288발을 싣고 기본 승무원 3명과 예비 인원 2명으로 운용한다. 사거리는 탄종에 따라 약 40~54km다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='pzh-2000';
UPDATE weapon_dictionary SET description='Radaa 300은 이집트 아랍산업화기구가 개발한 궤도형 다연장로켓이다. 개량 ATS-59G 차체에 자주장전 발사대 1개를 탑재한다. 탄종에 따라 122mm 로켓 20발, 220mm 6발, 300mm 4발 또는 610mm 1발을 적재한다. 220mm 사거리는 25~75km, 300mm는 30~150km, 610mm는 100~290km이며 전개 2분, 자체 재장전 3분이다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='radaa-300';
UPDATE weapon_dictionary SET description='S-80 Plus급은 스페인이 설계·건조한 재래식 잠수함이다. 길이 약 80m, 수중배수량 약 3,000t이며 바이오에탄올 기반 AIP를 탑재한다. S-81 Isaac Peral을 선도함으로 총 4척이 계획됐다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='s80-plus';
UPDATE weapon_dictionary SET description='SILAM은 스페인 육군용 다연장로켓 사업으로 2023년 도입 승인을 받았으나 2025년 계약이 취소되어 현역 배치된 장비가 아니다. 후속 사업은 별도 체계로 추진 중이다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='silam';
UPDATE weapon_dictionary SET description='9K58 Smerch는 러시아 툴라의 스플라브가 생산하는 300mm 다연장로켓으로, 1988년 러시아군에 배치됐다. 발사차는 MAZ-543M 8륜 차체에 12연장 발사관을 탑재하며 승무원은 4명이다. 9M55K 로켓은 길이 7.5m, 중량 800kg 초과, 사거리 20~70km다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='smerch';
UPDATE weapon_dictionary SET description='트리덴테급은 포르투갈 해군의 재래식 잠수함 2척이다. NRP Tridente는 2010년 취역했으며 수중배수량 2,020t, 길이 67.9m다. 두 함정의 이름은 Tridente와 Arpão다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='tridente-class';
UPDATE weapon_dictionary SET description='19식은 일본 육상자위대의 155mm 52구경 차륜형 자주포로, 8륜 트럭 차체에 탑재된다. 99식 자주포와 포 계통을 공유하며 승무원 5명, 차체 크기 약 11.4×2.5×3.4m, 최고속도 90km/h다. 포탄은 자동 장전하고 장약은 수동으로 넣는다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='type-19-sph';
UPDATE weapon_dictionary SET description='바스쿠 다 가마급은 포르투갈 해군의 수상전투함급으로 F330 Vasco da Gama, F331 Álvares Cabral, F332 Corte-Real 세 척으로 구성된다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='vasco-da-gama-class';
UPDATE weapon_dictionary SET description='빅토리아급은 캐나다 해군이 운용하는 재래식 디젤-전기 잠수함으로, 영국 Type 2400 Upholder급을 바탕으로 한다. 길이 70.3m, 수상배수량 2,168t, 수중배수량 2,455t이며 속력은 수상 12노트, 수중 20노트다. 승조원은 48명이고 533mm 함수 어뢰발사관 6문에 Mk 48 어뢰 최대 18발을 탑재한다.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='victoria-class';
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES (17,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
UPDATE metadata SET value=CAST(value AS INTEGER)+1 WHERE key='revision';
